import numpy as np


def kl_normal_std(mu, logvar):
    return float(0.5 * (mu * mu + np.exp(0.5 * logvar) - 1.0 - logvar))


def kl_vector(mu, logvar):
    mu = np.asarray(mu, dtype=float)
    logvar = np.asarray(logvar, dtype=float)
    return float(0.5 * np.sum(mu ** 2 + np.exp(logvar) - 1.0 - logvar))
